local HopperGateMaker = {}
local PRODUCTS = {
    iron_hoppergate = { name = "Železni zapornica za lijake", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zapornica za lijake za mlinarje." },
    bronze_hoppergate = { name = "Bronast zapornica za lijake", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zapornica za lijake za mlinarje." },
    silver_hoppergate = { name = "Srebrn zapornica za lijake", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zapornica za lijake za mlinarje." },
    gilded_hoppergate = { name = "Pozlačen zapornica za lijake", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zapornica za lijake za mlinarje." },
    jewel_set_hoppergate = { name = "Draguljast zapornica za lijake", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zapornica za lijake za mlinarje." },
    royal_sovereign_hoppergate = { name = "Kraljevski suveren zapornica za lijake", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zapornica za lijake z biseri za krono." },
}
local BUILDINGS = {
    hoppergate_workshop = { name = "Hoppergate delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hoppergate_house = { name = "Hoppergate hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hoppergate_atelier = { name = "Mojstrski hoppergate atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hoppergate_palace = { name = "Suverena hoppergate palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HopperGateMaker.ironStock=16; HopperGateMaker.bronzeStock=12; HopperGateMaker.woodStock=12; HopperGateMaker.leatherStock=10; HopperGateMaker.silverStock=8; HopperGateMaker.goldStock=6; HopperGateMaker.jewelStock=4; HopperGateMaker.pearlStock=4
HopperGateMaker.productStock = {}; HopperGateMaker.buildings = {}; HopperGateMaker.maker = nil; HopperGateMaker.activeMaking = {}; HopperGateMaker.totalProducts = 0; HopperGateMaker.dayTimer = 0
function HopperGateMaker.init() HopperGateMaker.ironStock=16; HopperGateMaker.bronzeStock=12; HopperGateMaker.woodStock=12; HopperGateMaker.leatherStock=10; HopperGateMaker.silverStock=8; HopperGateMaker.goldStock=6; HopperGateMaker.jewelStock=4; HopperGateMaker.pearlStock=4; HopperGateMaker.productStock={}; HopperGateMaker.buildings={}; HopperGateMaker.maker=nil; HopperGateMaker.activeMaking={}; HopperGateMaker.totalProducts=0; HopperGateMaker.dayTimer=0; print("[HopperGateMaker] Royal Hopper Gate Maker System initialized (6 products, 4 buildings)") end
function HopperGateMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HopperGateMaker.maker={name=n or ("Zaporničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaporničar najet: %s (spretnost: %d)",HopperGateMaker.maker.name,s),"success") end; return true end
function HopperGateMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HopperGateMaker.build(id) local ok,e=HopperGateMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HopperGateMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HopperGateMaker.getQualityBonus() local b=0; for _,bd in ipairs(HopperGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HopperGateMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HopperGateMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HopperGateMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HopperGateMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HopperGateMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HopperGateMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HopperGateMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HopperGateMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HopperGateMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HopperGateMaker.buildings==0 then return false,"Potrebna zapornična delavnica" end; if not HopperGateMaker.maker then return false,"Potreben zaporničar" end; return true end
function HopperGateMaker.make(pt,qty) qty=qty or 1; local ok,e=HopperGateMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HopperGateMaker.ironStock=HopperGateMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HopperGateMaker.bronzeStock=HopperGateMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HopperGateMaker.woodStock=HopperGateMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HopperGateMaker.leatherStock=HopperGateMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HopperGateMaker.silverStock=HopperGateMaker.silverStock-d.silverCost*qty end; if d.goldCost then HopperGateMaker.goldStock=HopperGateMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HopperGateMaker.jewelStock=HopperGateMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HopperGateMaker.pearlStock=HopperGateMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HopperGateMaker.maker then t=math.max(1,t-math.floor(HopperGateMaker.maker.skill/13)) end; table.insert(HopperGateMaker.activeMaking,{id="hoppergate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HopperGateMaker.completeMaking(m) local q=1.0+(HopperGateMaker.getQualityBonus()/100); if HopperGateMaker.maker then q=q+(HopperGateMaker.maker.skill/140) end; q=math.min(2.5,q); HopperGateMaker.productStock[m.productType]=(HopperGateMaker.productStock[m.productType] or 0)+m.quantity; HopperGateMaker.totalProducts=HopperGateMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HopperGateMaker.maker then HopperGateMaker.maker.itemsMade=HopperGateMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HopperGateMaker.maker.skill=math.min(100,HopperGateMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zapornica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hoppergate.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HopperGateMaker.update(dt) if not _G.state then return end; HopperGateMaker.dayTimer=HopperGateMaker.dayTimer+dt; if HopperGateMaker.dayTimer>=30 then HopperGateMaker.dayTimer=0; for i=#HopperGateMaker.activeMaking,1,-1 do local m=HopperGateMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HopperGateMaker.completeMaking(m); table.remove(HopperGateMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HopperGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HopperGateMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HopperGateMaker.getStats() return {ironStock=HopperGateMaker.ironStock,bronzeStock=HopperGateMaker.bronzeStock,woodStock=HopperGateMaker.woodStock,leatherStock=HopperGateMaker.leatherStock,silverStock=HopperGateMaker.silverStock,goldStock=HopperGateMaker.goldStock,jewelStock=HopperGateMaker.jewelStock,pearlStock=HopperGateMaker.pearlStock,productStock=HopperGateMaker.productStock,numBuildings=#HopperGateMaker.buildings,hasMaker=HopperGateMaker.maker~=nil,makerName=HopperGateMaker.maker and HopperGateMaker.maker.name or "—",makerSkill=HopperGateMaker.maker and HopperGateMaker.maker.skill or 0,activeMaking=#HopperGateMaker.activeMaking,totalProducts=HopperGateMaker.totalProducts} end
return HopperGateMaker
